<?php
 namespace Pterodactyl\Models\Dezerx; use Pterodactyl\Models\Model; use Pterodactyl\Models\User; use Illuminate\Database\Eloquent\Relations\BelongsTo; class StaffProfile extends Model { public const RESOURCE_NAME = 'staff_profile'; protected $table = 'dezerx_staff_profiles'; protected $guarded = ['id']; protected $casts = [ 'user_id' => 'int', 'available' => 'bool', 'max_active' => 'int', 'tags' => 'array', 'last_active_at' => 'datetime', ]; public static array $validationRules = [ 'user_id' => 'required|int|exists:users,id', 'available' => 'boolean', 'discord_id' => 'nullable|string|max:32', 'max_active' => 'int|between:1,50', ]; public function user(): BelongsTo { return $this->belongsTo(User::class); } } 